            arrowStyle = "classic",
            arrowFPS = 2,
            arrowleft = _G.GetScreenWidth() / 2.05,
            arrowtop = -(_G.GetScreenHeight() / 1.5),
            arrowTextAppearance = APR:CreateTextAppearanceDefaults(true, {
