            }),
            -- map
            mapMinimapSameColor = true,
            showMapLine = true,
            showMapLineColor = APR.Color.lightGreen,
            showMapLineThickness = 8,
            mapshowNextSteps = true,
            mapshowNextStepsColor = APR.Color.lightGreen,
