            minimapshowNextStepsCount = 2,
            minimapshowNextStepsSize = 16,
            minimapshowNextStepsTextScale = 1,
            minimapshowNextStepsColorText = APR.Color.gold,
            -- Heirloom
            heirloomFrame = {},
            heirloomWarning = false,
            heirloomTextAppearance = APR:CreateTextAppearanceDefaults(true, {
                accentColor = APR.Color.gold,
            }),
            --buff
            buffFrame = {},
            xpBuffFrame = { x = 280, y = 0, point = "CENTER" },
            showXPBuffOverlay = true,
            hiddenXPBonuses = {},
            -- group
            groupFrame = {},
            showGroup = true,
